Node* rotateRight(Node* z) {
    Node* y = z->left;
    Node* T = y->right;

    y->right = z;
    z->left = T;

    z->height = 1 + max(height(z->left), height(z->right));
    y->height = 1 + max(height(y->left), height(y->right));

    return y; // new root of this subtree
}

Node* rotateLeft(Node* z) {
    Node* y = z->right;
    Node* T = y->left;

    y->left = z;
    z->right = T;

    z->height = 1 + max(height(z->left), height(z->right));
    y->height = 1 + max(height(y->left), height(y->right));

    return y;
}

struct Node {
    int key, height;
    Node *left, *right;
    Node(int k) : key(k), height(1), left(nullptr), right(nullptr) {}
};

int height(Node* n) { return n ? n->height : 0; }
int balanceFactor(Node* n) { return n ? height(n->left) - height(n->right) : 0; }

Node* insert(Node* node, int key) {
    if (!node) return new Node(key);
    if (key < node->key) node->left = insert(node->left, key);
    else if (key > node->key) node->right = insert(node->right, key);
    else return node; // duplicate keys not inserted

    node->height = 1 + max(height(node->left), height(node->right));
    int bf = balanceFactor(node);

    if (bf > 1 && key < node->left->key) return rotateRight(node);          // Left Left
    if (bf < -1 && key > node->right->key) return rotateLeft(node);         // Right Right
    if (bf > 1 && key > node->left->key) {                                  // Left Right
        node->left = rotateLeft(node->left);
        return rotateRight(node);
    }
    if (bf < -1 && key < node->right->key) {                                // Right Left
        node->right = rotateRight(node->right);
        return rotateLeft(node);
    }
    return node; // already balanced
}
